import{_ as t,o,c as r,a2 as s}from"./chunks/framework.CqdVOxXJ.js";const a="/rakkii-cars-guide/screenshots/v2/a12-pay-tab.png",n="/rakkii-cars-guide/screenshots/v2/a14-more-papers.png",i="/rakkii-cars-guide/screenshots/v2/a13-pay-paid.png",f=JSON.parse('{"title":"6. Bill and collect","description":"","frontmatter":{},"headers":[],"relativePath":"desk/job/06-bill-and-collect.md","filePath":"desk/job/06-bill-and-collect.md","lastUpdated":1794621279000}'),l={name:"desk/job/06-bill-and-collect.md"};function c(h,e,d,p,g,m){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="_6-bill-and-collect" tabindex="-1">6. Bill and collect <a class="header-anchor" href="#_6-bill-and-collect" aria-label="Permalink to &quot;6. Bill and collect&quot;">​</a></h1><p><strong>Who:</strong> Owner or admin · <strong>Where:</strong> the job&#39;s <strong>Pay</strong> tab · <strong>Status after:</strong> no change</p><p>Billing doesn&#39;t change the status. It records what the customer owes and what they paid.</p><h2 id="read-the-summary-first" tabindex="-1">Read the Summary first <a class="header-anchor" href="#read-the-summary-first" aria-label="Permalink to &quot;Read the Summary first&quot;">​</a></h2><p>The <strong>Summary</strong> card at the top of <strong>Pay</strong> shows <strong>Customer owes</strong>, <strong>Insurer owes</strong>, <strong>Cash in</strong> and <strong>Deposit still due</strong>. Press <strong>More figures</strong> for cost, sell and withholding.</p><p><img src="'+a+'" alt="Pay tab before billing"></p><h2 id="post-the-customer-invoice" tabindex="-1">Post the customer invoice <a class="header-anchor" href="#post-the-customer-invoice" aria-label="Permalink to &quot;Post the customer invoice&quot;">​</a></h2><ol><li>On the <strong>Invoices</strong> card, press <strong>Bill customer ₱…</strong> (the amount of the approved customer lines).</li><li>The app asks, for example, &quot;Bill the customer ₱2,300.00?&quot; Press <strong>Create invoice</strong>. The invoice is posted with the next number in the VAT or Non-VAT series. <ul><li>Billing before the work is finished? The app warns you may need a credit note if lines change.</li></ul></li><li>Print it from <strong>Print ▾</strong>, or from <strong>Work › Job order › More papers</strong>, which has every paper for the job.</li></ol><p><img src="'+n+'" alt="More papers menu"></p><div class="warning custom-block"><p class="custom-block-title">Posting is final</p><p>A posted invoice can&#39;t be edited. To undo it you need a void or a credit note. See <a href="/rakkii-cars-guide/desk/fix-a-mistake">Fix a mistake</a>.</p></div><h2 id="record-the-payment" tabindex="-1">Record the payment <a class="header-anchor" href="#record-the-payment" aria-label="Permalink to &quot;Record the payment&quot;">​</a></h2><ol><li>Under <strong>Record a payment</strong>, set <strong>Who paid</strong>: Customer.</li><li>Type the <strong>Amount</strong>, or press the <strong>Fill ₱…</strong> button next to it. While a deposit is still due, <strong>Fill</strong> enters the deposit; after that it enters what&#39;s left.</li><li>Choose the <strong>Method</strong>. For a bank transfer, choose the <strong>Bank account</strong> and fill in <strong>Reference</strong>.</li><li>Choose the invoice under <strong>Apply to invoice</strong>, and the account in <strong>Deposited to</strong> if you track it.</li><li>Press <strong>Record payment</strong>. The app asks, for example, &quot;Record ₱2,300.00 from the customer?&quot; Press <strong>Record payment</strong> again.</li></ol><p><strong>Customer owes</strong> should now read <strong>₱0.00</strong>.</p><p><img src="'+i+'" alt="Summary after the final payment"></p><div class="tip custom-block"><p class="custom-block-title">Paid by GCash or Maya from the pay link?</p><p>The customer&#39;s screenshot shows as a payment proof. Press <strong>Review payment proof</strong> on the Pay tab and confirm it once you&#39;ve checked the money arrived. Don&#39;t record it twice.</p></div><p>By default the car is held until the customer has paid. The owner can change this per job on the <strong>Release</strong> tab (<strong>Release rules</strong>).</p><p><strong>Next:</strong> <a href="/rakkii-cars-guide/desk/job/07-release">7. Release the car</a></p>',17)])])}const b=t(l,[["render",c]]);export{f as __pageData,b as default};
